export type Screen = 'menu'|'howto'|'levels'|'upgrades'|'settings'|'race'|'result';
export interface Stats { jump:number; spin:number; stamina:number; explosion:number }
export interface Level { name:string; length:number; slope:number; bumps:number; gaps:number; theme:string; color:string; height:number }
export interface Actor { x:number;y:number;vx:number;vy:number;angle:number;spin:number;grounded:boolean;integrity:number;badLandings:number;damage:number;airTime:number;maxHeight:number;maxSpin:number;lastAngle:number;spinCount:number;headLaunched:boolean;headX:number;headY:number;headVx:number;headVy:number;headAngle:number;headParticles:number;parts:Part[];ai:boolean;name:string;color:string;dead:boolean;won:boolean;trail:{x:number;y:number}[] }
export interface Part {type:string;x:number;y:number;vx:number;vy:number;angle:number;spin:number;life:number;color:string}
export interface RaceResult {winner:string;place:number;spins:number;height:number;distance:number;awards:boolean[];elapsed:number}
const LEVEL_NAMES=['Rookie Ridge','Bubble Trouble','Sunny Side Up','The Big Dip','Moon Bounce','Crater Creator','Astro Alley','Meteor Mosh','The Long Fall','Comet Canyon','Lunar Loops','Orbit Of Doom','Rocket Rumble','Star Struck','The Great Crater','Neon Nebula','Space Jumble','Planet Pogo','Galaxy Gauntlet','Black Hole Boulevard','The Final Frontier','Supernova Speedway','Cosmic Catastrophe','The Last Launch','Robot Renaissance','Infinity Impact','Meteor Mayhem','The End Is Nigh','Victory Lap','Legends Never Die'];
const THEMES=[['sky','#73cce0'],['sunset','#ffb56e'],['mint','#a4dfad'],['space','#5466ac'],['moon','#a0abd0'],['candy','#f29abd'],['night','#62609b'],['mars','#da8b69']];
export const LEVELS:Level[]=LEVEL_NAMES.map((name,i)=>{const theme=THEMES[i%THEMES.length];return{name,length:1200+i*145,slope:0.15+Math.min(i*.012,.35),bumps:5+Math.floor(i*.85),gaps:Math.floor(i/3),theme:theme[0],color:theme[1],height:90+Math.min(i*4,80)}});
export const DEFAULT_STATS:Stats={jump:1,spin:1,stamina:1,explosion:1};
const clamp=(v:number,a:number,b:number)=>Math.max(a,Math.min(b,v));
export class Game {
 canvas:HTMLCanvasElement;ctx:CanvasRenderingContext2D;W=480;H=720;screen:Screen='menu';levelIndex=0;stats:Stats={...DEFAULT_STATS};chips=3;unlocked=1;cleared=new Set<number>();sound=true;solo=false;aiCount=2;actors:Actor[]=[];player!:Actor;parts:Part[]=[];particles:{x:number;y:number;vx:number;vy:number;life:number;color:string;size:number;type:string}[]=[];cameraX=0;cameraY=0;groundY=520;distance=0;raceElapsed=0;result:RaceResult|null=null;held=false;paused=false;state:string='ready';gameTime=0;kickTimer=0;sessionPlayers=1;turn=0;settingsBot=2;raceStats={spins:0,height:0,distance:0};shake=0;flash=0;lastTs=0;acc=0;frame=0;backBuffer:HTMLCanvasElement;bgCtx:CanvasRenderingContext2D;seed=1;muteMusic=false;autoRun=false;onMenu:()=>void=()=>{};
 constructor(canvas:HTMLCanvasElement){this.canvas=canvas;const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)throw Error('Canvas 2D not available');this.ctx=ctx;this.backBuffer=document.createElement('canvas');this.backBuffer.width=this.W;this.backBuffer.height=this.H;this.bgCtx=this.backBuffer.getContext('2d')!;this.bind();this.resize();this.loop(0)}
 resize(){const dpr=Math.min(window.devicePixelRatio||1,2),r=this.canvas.getBoundingClientRect();this.canvas.width=Math.round(r.width*dpr);this.canvas.height=Math.round(r.height*dpr);this.ctx.imageSmoothingEnabled=false}
 bind(){window.addEventListener('resize',()=>this.resize());const start=()=>{if(this.screen==='race'&&!this.paused)this.held=true};const stop=()=>this.held=false;window.addEventListener('keydown',e=>{if(['Space','ArrowDown','ArrowUp','KeyZ','Enter'].includes(e.code)){if(this.screen==='race'){e.preventDefault();start()}else if(e.code==='Escape')this.menu()}});window.addEventListener('keyup',e=>{if(['Space','ArrowDown','ArrowUp','KeyZ','Enter'].includes(e.code))stop()});window.addEventListener('blur',stop);this.canvas.addEventListener('pointerdown',()=>{if(this.screen==='race')start()});window.addEventListener('pointerup',stop)}
 rand(){this.seed=(this.seed*1664525+1013904223)>>>0;return this.seed/4294967296}
 menu(){this.screen='menu';this.paused=false;this.held=false}
 beginRace(index=this.levelIndex,opts:{solo?:boolean;players?:number}={}){this.levelIndex=index;this.solo=opts.solo??false;this.sessionPlayers=opts.players??1;this.turn=0;this.seed=145670+index*7919;this.parts=[];this.particles=[];this.cameraX=0;this.cameraY=0;this.distance=0;this.raceElapsed=0;this.result=null;this.shake=0;this.flash=0;this.paused=false;this.held=false;this.state='kick';this.gameTime=0;this.kickTimer=0;this.actors=[];this.player=this.makeActor(false,'YOU','#ff814f');this.player.x=115;this.player.y=250;this.player.vx=0;this.actors.push(this.player);if(!this.solo){for(let i=0;i<this.settingsBot;i++){const colors=['#68c8bd','#a285ed','#f2bf57'];const a=this.makeActor(true,['BEEP','BOP','ZIP'][i],colors[i]);a.x=87-i*40;a.y=270+i*6;a.vx=0;this.actors.push(a)}}this.screen='race'}
 makeActor(ai:boolean,name:string,color:string):Actor{return{x:0,y:0,vx:0,vy:0,angle:0,spin:0.06,grounded:true,integrity:100,badLandings:0,damage:0,airTime:0,maxHeight:0,maxSpin:0,lastAngle:0,spinCount:0,headLaunched:false,headX:0,headY:0,headVx:0,headVy:0,headAngle:0,headParticles:0,parts:[],ai,name,color,dead:false,won:false,trail:[]}}
 ground(x:number):number{const l=LEVELS[this.levelIndex];let y=535+Math.sin(x*.006+this.levelIndex)*11+Math.sin(x*.018+this.levelIndex*.7)*4;for(let i=0;i<l.bumps;i++){const bx=270+i*(l.length-280)/Math.max(l.bumps,1)+Math.sin(i*18+this.levelIndex)*25,dx=x-bx;if(Math.abs(dx)<43)y-=Math.cos(dx/43*Math.PI/2)*l.height*(.4+((i*7+this.levelIndex)%5)*.12)}for(let i=0;i<l.gaps;i++){const gx=400+i*(l.length-420)/Math.max(l.gaps,1)+Math.sin(i*13+this.levelIndex)*34;if(Math.abs(x-gx)<31)y+=Math.max(0,1-Math.abs(x-gx)/31)*75}return y}
