let selectedLevel=0;let quickSolo=false;let sessionPlayers=1;let currentPlayer=0;let resultShown=false;
const save=()=>{data={chips:game.chips,unlocked:game.unlocked,cleared:[...game.cleared],stats:{...game.stats},sound:game.sound,bots:game.settingsBot};localStorage.setItem('kamikaze-save',JSON.stringify(data))};
const esc=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
function btn(text:string,action:string,cls=''){return `<button class="btn ${cls}" data-action="${action}">${text}</button>`}
function show(html:string){ui.innerHTML=html}
function menu(){game.menu();controls.classList.add('hidden');touchHint.classList.add('hidden');show(`<div class="screen"><div class="logo-kicker">DIGITAL CHAOS PRESENTS</div><div class="logo">KAMIKAZE<br>ROBOTS</div><div class="subtitle">Tiny robots. Big hills. Questionable engineering.</div><div class="button-row">${btn('🏁 &nbsp; TOURNAMENT','start-tournament')}${btn('⚡ &nbsp; QUICK RACE','quick','secondary')}${btn('🔧 &nbsp; GARAGE & UPGRADES','upgrades','gold')}${btn('❔ &nbsp; HOW TO PLAY','howto','secondary')}</div><div class="screen-footer">${game.chips} chips &nbsp;•&nbsp; ${game.cleared.size}/${LEVELS.length} courses cleared &nbsp;•&nbsp; SPACE / HOLD TO BRAKE</div></div>`)}
function howto(){game.screen='howto';show(`<div class="screen"><div class="card"><div class="topline">THE MANUAL (SORT OF)</div><h2>One button. Zero safety gear.</h2><p>Our brave little tin can starts with a <b>giant boot to the backside</b>. Off it goes!</p><p><b>Let go</b> to spin clockwise. More spins mean a stronger bounce. <b>Hold anywhere</b> (or SPACE / ↓) to brake and point feet-down before landing.</p><p>Feet first = big bouncy launch. Face-plant = <b>arms pop off first</b>, then legs. Lose them all and the next hit ejects your head like a flaming comet. Heads can still win!</p><p>Grab up to <b>4 chips</b>: win, spin, soar and go the distance. Spend chips on Jump, Spin, Stamina and Explosion upgrades.</p><p class="race-note">Tip: start braking near the top of your jump—not at the last millisecond!</p>${btn('GOT IT — LET’S ROLL','menu','gold')}</div></div>`)}
function levels(mode:'tournament'|'quick'){game.screen='levels';selectedLevel=mode==='tournament'?Math.max(0,game.unlocked-1):Math.min(game.unlocked-1,selectedLevel);show(`<div class="screen"><div class="card"><div class="topline">${mode==='tournament'?'TOURNAMENT CIRCUIT':'PICK YOUR HILL'}</div><h2>${mode==='tournament'?'Choose your challenge':'Quick race / practice'}</h2><p class="race-note">${mode==='tournament'?'Clear a course to unlock the next. Replay any cleared course for missing chips.':'Race the bots or practice solo. Progress is saved.'}</p><div class="level-list">${LEVELS.map((l,i)=>`<button class="level-tile ${i===selectedLevel?'selected':''}" data-action="level" data-level="${i}" ${i>=game.unlocked?'disabled':''} title="${esc(l.name)}">${i+1}${game.cleared.has(i)?'★':''}</button>`).join('')}</div><div class="race-note" id="level-desc">${LEVELS[selectedLevel].name} · ${Math.round(LEVELS[selectedLevel].length/10)} m · ${selectedLevel<4?'rolling green hills':LEVELS[selectedLevel].theme+' world'}</div><div class="button-row">${btn(mode==='tournament'?'START TOURNAMENT RACE':'START QUICK RACE','start-selected','gold')}${mode==='quick'?btn(quickSolo?'SOLO PRACTICE: ON':'SOLO PRACTICE: OFF','toggle-solo','secondary'):''}${btn('BACK TO GARAGE','menu','secondary')}</div></div></div>`)}
const names:{key:keyof Stats;label:string;desc:string;icon:string}[]=[{key:'jump',label:'JUMP',desc:'More punch in every bounce',icon:'↟'},{key:'spin',label:'SPIN',desc:'Faster free spin in the air',icon:'⟳'},{key:'stamina',label:'STAMINA',desc:'Tougher limbs; fewer breaks',icon:'♥'},{key:'explosion',label:'EXPLOSION',desc:'Rocket-head launch distance',icon:'☄'}];
function upgrades(){game.screen='upgrades';show(`<div class="screen"><div class="card upgrade-screen"><div class="topline">TINKER WITH QUESTIONABLE SCIENCE</div><h2>Robot garage</h2><p>Chips available: <span class="chip-count">🟡 ${game.chips}</span></p>${names.map(n=>`<div><div class="upgrade"><div><span class="upgrade-name">${n.icon} ${n.label}</span><div class="race-note">${n.desc}</div></div><div class="upgrade-bar"><div class="upgrade-fill" style="width:${game.stats[n.key]*10}%"></div></div><span class="upgrade-num">${game.stats[n.key]}</span><button class="btn" data-action="buy" data-stat="${n.key}" ${game.stats[n.key]>=10||game.chips<upgradeCost(game.stats[n.key])?'disabled':''}>+</button></div><div class="race-note" style="text-align:right;margin-top:-8px">Next upgrade: ${upgradeCost(game.stats[n.key])} chip${upgradeCost(game.stats[n.key])>1?'s':''}</div></div>`).join('')}<div class="button-row">${btn('BACK TO MENU','menu','secondary')}</div></div></div>`)}
function upgradeCost(level:number){return level<4?1:level<7?2:3}
function settings(){game.screen='settings';show(`<div class="screen"><div class="card"><div class="topline">PREFERENCES</div><h2>Race settings</h2><p>Opponents: <b>${game.settingsBot}</b></p><div class="button-row">${btn('−  FEWER BOTS','bot-minus','secondary')}${btn('+  MORE BOTS','bot-plus','secondary')}${btn(game.sound?'♪  SOUND: ON':'♪  SOUND: OFF','sound','gold')}${btn('BACK TO MENU','menu','secondary')}</div><p class="race-note">You can also mute during a race with ♪.</p></div></div>`)}
function startRace(idx:number,solo=false,players=1){resultShown=false;currentPlayer=0;game.beginRace(idx,{solo,players});controls.classList.remove('hidden');touchHint.classList.remove('hidden');renderHud()}
function renderHud(){if(game.screen!=='race')return;const a=game.player;const level=LEVELS[game.levelIndex];const dist=Math.floor(game.distance/10);const goal=Math.round(level.length/10);const spinGoal=Math.max(2,2+Math.floor(game.levelIndex/8));const hGoal=100+game.levelIndex*2;const checks=[a.won||game.distance>=level.length,a.maxSpin>=spinGoal,a.maxHeight>=hGoal,game.distance>=level.length*.8];show(`<div class="race-hud"><div class="hud-top"><div><div class="hud-distance">${dist}<span> m</span></div><div class="hud-level">${esc(level.name)} · ${dist}/${goal} m</div></div><div class="hud-position">${game.actors.filter(o=>o.won||o.x>a.x).length+1}${ordinal(game.actors.filter(o=>o.won||o.x>a.x).length+1)}</div></div><div class="hud-objectives">${checks.map((v,i)=>`<span class="objective ${v?'done':''}">${v?'✓':'○'} ${['1st','Spin','Air','Go'][i]}</span>`).join('')}</div>${game.paused?`<div class="screen"><div class="card"><h2>PAUSED</h2><p>Robot safety inspection in progress.</p><div class="button-row">${btn('RESUME','resume','gold')}${btn('QUIT RACE','quit','secondary')}</div></div></div>`:''}<div class="chip-tracker">${checks.map(v=>`<span class="chip-dot ${v?'done':''}"></span>`).join('')}</div><button id="hold-control" class="hold-control ${game.held?'active':''}"><span class="hold-dot"></span> HOLD TO BRAKE &nbsp;↓</button></div>`);const b=document.querySelector<HTMLButtonElement>('#hold-control');if(b){const down=(e:Event)=>{e.preventDefault();game.held=true;b.classList.add('active')};const up=(e:Event)=>{e.preventDefault();game.held=false;b.classList.remove('active')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointerleave',up);b.addEventListener('pointercancel',up)}}
function ordinal(n:number){return n===1?'ST':n===2?'ND':n===3?'RD':'TH'}
function renderResult(){const r=game.result!;const got=r.awards.filter(Boolean).length;show(`<div class="screen"><div class="card"><div class="topline">${r.place===1?'CHAMPION!':'RACE COMPLETE'}</div><h2>${r.place===1?'Victory!':r.place===2?'So close!':'Good effort!'}</h2><p>${r.place===1?'The robot union has filed a complaint about that boot.':`${esc(game.player.name)} is mostly in one piece. Mostly.`}</p><div class="result-badges">${r.awards.map((ok,i)=>`<div class="result-badge"><strong>${ok?'🟡 +1':'○ 0'}</strong>${['Finish 1st','Spin goal','Jump height','Race distance'][i]}</div>`).join('')}</div><p>Spins: <b>${r.spins}</b> &nbsp; Max air: <b>${r.height}m</b></p><p>Chips earned: <span class="chip-count">${got}</span> &nbsp; Total: <span class="chip-count">${game.chips}</span></p><div class="button-row">${game.levelIndex+1<game.unlocked&&game.levelIndex+1<LEVELS.length?btn('NEXT LEVEL →','next','gold'):btn('RACE AGAIN','again','gold')}${btn('GARAGE & UPGRADES','upgrades','secondary')}${btn('MAIN MENU','menu','secondary')}</div></div></div>`);controls.classList.add('hidden');touchHint.classList.add('hidden');save()}
function render(){if(game.screen==='race'){if(game.state==='result'){if(!resultShown){resultShown=true;renderResult()}}else if(game.frame%3===0)renderHud()}else if(game.screen==='result'&&game.result)renderResult()}
ui.addEventListener('click',e=>{const target=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!target)return;const action=target.dataset.action!;switch(action){case'menu':menu();break;case'howto':howto();break;case'start-tournament':levels('tournament');break;case'quick':levels('quick');break;case'upgrades':upgrades();break;case'settings':settings();break;case'level':selectedLevel=Number(target.dataset.level);levels('quick');break;case'start-selected':startRace(selectedLevel,quickSolo,sessionPlayers);break;case'toggle-solo':quickSolo=!quickSolo;levels('quick');break;case'buy':{const k=target.dataset.stat as keyof Stats;const cost=upgradeCost(game.stats[k]);if(game.chips>=cost&&game.stats[k]<10){game.chips-=cost;game.stats[k]++;game.stats={...game.stats};save();upgrades()}break}case'bot-minus':game.settingsBot=Math.max(0,game.settingsBot-1);save();settings();break;case'bot-plus':game.settingsBot=Math.min(3,game.settingsBot+1);save();settings();break;case'sound':game.sound=!game.sound;save();settings();break;case'resume':game.paused=false;renderHud();break;case'quit':menu();break;case'again':startRace(game.levelIndex,game.solo);break;case'next':startRace(Math.min(game.levelIndex+1,game.unlocked-1));break}}
);
pauseBtn.addEventListener('click',()=>{if(game.screen!=='race')return;game.paused=!game.paused;renderHud()});soundBtn.addEventListener('click',()=>{game.sound=!game.sound;soundBtn.textContent=game.sound?'♪':'×';save()});
// Add optional settings access via keyboard S; tournament starts with first available course.
window.addEventListener('keydown',e=>{if(e.code==='Escape'&&game.screen==='race'){game.paused=!game.paused;renderHud()}if(e.code==='KeyS'&&game.screen==='menu')settings()});
menu();setInterval(render,50);

