14:  constructor(canvas:HTMLCanvasElement){this.canvas=canvas;const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)throw Error('Canvas 2D not available');this.ctx=ctx;this.backBuffer=document.createElement('canvas');this.backBuffer.width=this.W;this.backBuffer.height=this.H;this.bgCtx=this.backBuffer.getContext('2d')!;this.bind();this.resize();this.loop(0)}
