20:  makeActor(ai:boolean,name:string,color:string):Actor{return{x:0,y:0,vx:0,vy:0,angle:0,spin:0.06,grounded:true,integrity:100,badLandings:0,damage:0,airTime:0,maxHeight:0,bestHeight:0,maxSpin:0,bestSpin:0,lastAngle:0,spinCount:0,bouncePower:0,powerReset:0,limbs:4,headLaunched:false,headX:0,headY:0,headVx:0,headVy:0,headAngle:0,headParticles:0,parts:[],ai,name,color,dead:false,won:false,trail:[]}}
21:  rawGround(x:number):number{const l=LEVELS[this.levelIndex],i=this.levelIndex;let y=535+Math.sin(x*.0032+i*.7)*l.slope*34+Math.sin(x*.011+i*1.7)*7+Math.sin(x*.027+i*.31)*3;for(let n=0;n<l.bumps;n++){const bx=250+n*(l.length-260)/Math.max(l.bumps,1)+Math.sin(n*18+i)*18,dx=x-bx,width=27+(n+i)%3*8;if(Math.abs(dx)<width)y-=Math.cos(dx/width*Math.PI/2)*l.height*(.48+((n*7+i)%5)*.11)}for(let n=0;n<l.gaps;n++){const gx=390+n*(l.length-410)/Math.max(l.gaps,1)+Math.sin(n*13+i)*27,dx=Math.abs(x-gx);if(dx<27)y+=Math.cos(dx/27*Math.PI/2)*(48+Math.min(i*2,36))}return y}
