  burst(x:number,y:number,n:number,color:string){for(let i=0;i<n;i++){const angle=this.rand()*Math.PI*2,speed=25+this.rand()*190;this.particles.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed-40,life:.25+this.rand()*.65,color,size:2+this.rand()*4,type:this.rand()<.3?'star':'dot'})}}

