src/game.ts:36: drawBackdrop(c:CanvasRenderingContext2D){const g=c.createLinearGradient(0,0,0,720);g.addColorStop(0,'#68c4dc');g.addColorStop(.65,'#d4f0cf');g.addColorStop(1,'#ffdfaa');c.fillStyle=g;c.fillRect(0,0,480,720);c.fillStyle='#ffdc75';c.beginPath();c.arc(383,122,50,0,Math.PI*2);c.fill();for(let i=0;i<7;i++){const x=i*93-20,y=350+Math.sin(i*2)*28;c.fillStyle=i%2?'#84cfa4':'#65bf9f';c.beginPath();c.ellipse(x,y,95,85,0,Math.PI,Math.PI*2);c.lineTo(x+95,560);c.lineTo(x-95,560);c.fill()}this.drawRobot(c,260,478,0,'#ff814f',1,false)}
src/game.ts:37: drawWorld(c:CanvasRenderingContext2D){const l=LEVELS[this.levelIndex],theme=l.theme;let top='#69c7df',middle='#c4eddb',hill='#70c78f',ground='#e7b666';if(theme==='space'||theme==='moon'||theme==='night'){top=theme==='moon'?'#777ba5':'#252a59';middle=theme==='moon'?'#b6b5c7':'#4a4b83';hill=theme==='moon'?'#85849e':'#62588d';ground=theme==='moon'?'#b3a78a':'#a98a72'}else if(theme==='sunset'||theme==='mars'){top=theme==='mars'?'#ce7162':'#ffb578';middle='#ffe0a2';hill=theme==='mars'?'#b86059':'#e7866d';ground='#b77961'}else if(theme==='candy'){top='#e992c5';middle='#f6d2e8';hill='#b998d8';ground='#c491b7'}else if(theme==='mint'){top='#93d7d0';middle='#d2f0c4';hill='#75c99f';ground='#c8ad6b'}const sky=c.createLinearGradient(0,0,0,570);sky.addColorStop(0,top);sky.addColorStop(.75,middle);sky.addColorStop(1,hill);c.fillStyle=sky;c.fillRect(0,0,480,720);this.drawSkyDetails(c,theme);const cam=this.cameraX,camY=this.cameraY;c.save();c.translate(-cam*.35,0);for(let i=0;i<7;i++){const x=i*120-60-(cam*.1%120);c.fillStyle=theme==='space'?'#f7d87566':'#fff4cf66';c.beginPath();c.ellipse(x,370+Math.sin(i*4)*20,70,23,0,0,Math.PI*2);c.fill()}c.restore();c.save();c.translate(-cam, -camY);const start=Math.floor((cam-50)/5)*5,end=Math.ceil((cam+600)/5)*5;c.beginPath();c.moveTo(start,this.ground(start));for(let x=start+5;x<=end;x+=5)c.lineTo(x,this.ground(x));c.lineTo(end,720+camY);c.lineTo(start,720+camY);c.closePath();c.fillStyle=ground;c.fill();c.strokeStyle=theme==='space'?'#e7d4a0':'#fff0b0';c.lineWidth=7;c.lineJoin='round';c.beginPath();c.moveTo(start,this.ground(start));for(let x=start+5;x<=end;x+=5)c.lineTo(x,this.ground(x));c.stroke();c.lineWidth=1;for(let x=Math.floor(start/40)*40;x<end;x+=40){const gy=this.ground(x);c.fillStyle='#74585a22';c.fillRect(x,gy+16,20,3);if(Math.floor(x/40)%3===0){c.fillStyle='#5eab75';c.beginPath();c.ellipse(x+15,gy+8,4,8,-.4,0,Math.PI*2);c.fill()}}this.drawFinish(c,l.length,this.ground(l.length));for(const p of this.parts)this.drawP