export const LEVELS:Level[]=LEVEL_NAMES.map((name,i)=>{const theme=THEMES[i%THEMES.length];return{name,length:1800+i*210,slope:0.15+Math.min(i*.016,.48),bumps:9+Math.floor(i*1.25),gaps:Math.floor(i/2.5),theme:theme[0],color:theme[1],height:90+Math.min(i*5,120)}});
