export class Game {
 canvas:HTMLCanvasElement;ctx:CanvasRenderingContext2D;W=480;H=720;screen:Screen='menu';levelIndex=0;stats:Stats={...DEFAULT_STATS};chips=3;unlocked=1;cleared=new Set<number>();sound=true;solo=false;aiCount=2;actors:Actor[]=[];player!:Actor;parts:Part[]=[];particles:{x:number;y:number;vx:number;vy:number;life:number;color:string;size:number;type:string}[]=[];cameraX=0;cameraY=0;groundY=520;distance=0;raceElapsed=0;result:RaceResult|null=null;held=false;paused=false;state:string='ready';gameTime=0;kickTimer=0;sessionPlayers=1;turn=0;settingsBot=2;raceStats={spins:0,height:0,distance:0};shake=0;flash=0;lastTs=0;acc=0;frame=0;backBuffer:HTMLCanvasElement;bgCtx:CanvasRenderingContext2D;seed=1;muteMusic=false;autoRun=false;onMenu:()=>void=()=>{};
