3: export interface Level { name:string; length:number; slope:number; bumps:number; gaps:number; theme:string; color:string; height:number }
4: export interface Actor { x:number;y:number;vx:number;vy:number;angle:number;spin:number;grounded:boolean;integrity:number;badLandings:number;damage:number;airTime:number;maxHeight:number;bestHeight:number;maxSpin:number;bestSpin:number;lastAngle:number;spinCount:number;bouncePower:number;powerReset:number;limbs:number;headLaunched:boolean;headX:number;headY:number;headVx:number;headVy:number;headAngle:number;headParticles:number;parts:Part[];ai:boolean;name:string;color:string;dead:boolean;won:boolean;trail:{x:number;y:number}[] }
5: export interface Part {type:string;x:number;y:number;vx:number;vy:number;angle:number;spin:number;life:number;color:string}
6: export interface RaceResult {winner:string;place:number;spins:number;height:number;distance:number;awards:boolean[];elapsed:number}
7: const LEVEL_NAMES=['Rookie Ridge','Bubble Trouble','Sunny Side Up','The Big Dip','Moon Bounce','Crater Creator','Astro Alley','Meteor Mosh','The Long Fall','Comet Canyon','Lunar Loops','Orbit Of Doom','Rocket Rumble','Star Struck','The Great Crater','Neon Nebula','Space Jumble','Planet Pogo','Galaxy Gauntlet','Black Hole Boulevard','The Final Frontier','Supernova Speedway','Cosmic Catastrophe','The Last Launch','Robot Renaissance','Infinity Impact','Meteor Mayhem','The End Is Nigh','Victory Lap','Legends Never Die'];
8: const THEMES=[['sky','#73cce0'],['sunset','#ffb56e'],['mint','#a4dfad'],['space','#5466ac'],['moon','#a0abd0'],['candy','#f29abd'],['night','#62609b'],['mars','#da8b69']];
9: export const LEVELS:Level[]=LEVEL_NAMES.map((name,i)=>{const theme=THEMES[i%THEMES.length];return{name,length:1800+i*210,slope:0.15+Math.min(i*.016,.48),bumps:9+Math.floor(i*1.25),gaps:Math.floor(i/2.5),theme:theme[0],color:theme[1],height:90+Math.min(i*5,120)}});
10: export const DEFAULT_STATS:Stats={jump:1,spin:1,stamina:1,explosion:1};
