19:function menu(){game.menu();controls.classList.add('hidden');touchHint.classList.add('hidden');show(`<div class="screen"><div class="logo-kicker">DIGITAL CHAOS PRESENTS</div><div class="logo">KAMIKAZE<br>ROBOTS</div><div class="subtitle">Tiny robots. Big hills. Questionable engineering.</div><div class="button-row">${btn('🏁 &nbsp; TOURNAMENT','start-tournament')}${btn('⚡ &nbsp; QUICK RACE','quick','secondary')}${btn('🔧 &nbsp; GARAGE & UPGRADES','upgrades','gold')}${btn('⚙ &nbsp; SETTINGS','settings','secondary')}${btn('❔ &nbsp; HOW TO PLAY','howto','secondary')}</div><div class="screen-footer">${game.chips} chips &nbsp;•&nbsp; ${game.cleared.size}/${LEVELS.length} courses cleared &nbsp;•&nbsp; SPACE / HOLD TO BRAKE</div></div>`)}
20:function howto(){game.screen='howto';show(`<div class="screen"><div class="card"><div class="topline">THE MANUAL (SORT OF)</div><h2>One button. Zero safety gear.</h2><p>Our brave little tin can starts with a <b>giant boot to the backside</b>. Off it goes!</p><p><b>Let go</b> to spin clockwise. More spins mean a stronger bounce. <b>Hold anywhere</b> (or SPACE / ↓) to brake and point feet-down before landing.</p><p>Feet first = big bouncy launch. Face-plant = <b>arms pop off first</b>, then legs. Lose them all and the next hit ejects your head like a flaming comet. Heads can still win!</p><p>Grab up to <b>4 chips</b>: win, spin, soar and go the distance. Spend chips on Jump, Spin, Stamina and Explosion upgrades.</p><p class="race-note">Tip: start braking near the top of your jump—not at the last millisecond!</p>${btn('GOT IT — LET’S ROLL','menu','gold')}</div></div>`)}
23:function upgrades(){game.screen='upgrades';show(`<div class="screen"><div class="card upgrade-screen"><div class="topline">TINKER WITH QUESTIONABLE SCIENCE</div><h2>Robot garage</h2><p>Chips available: <span class="chip-count">🟡 ${game.chips}</span></p>${names.map(n=>`<div><div class="upgrade"><div><span class="upgrade-name">${n.icon} ${n.label}</span><div class="race-note">${n.desc}</div></div><div class="upgrade-bar"><div class="upgrade-fill" style="width:${game.stats[n.key]*10}%"></div></div><span class="upgrade-num">${game.stats[n.key]}</span><button class="btn" data-action="buy" data-stat="${n.key}" ${game.stats[n.key]>=10||game.chips<upgradeCost(game.stats[n.key])?'disabled':''}>+</button></div><div class="race-note" style="text-align:right;margin-top:-8px">Next upgrade: ${upgradeCost(game.stats[n.key])} chip${upgradeCost(game.stats[n.key])>1?'s':''}</div></div>`).join('')}<div class="button-row">${btn('BACK TO MENU','menu','secondary')}</div></div></div>`)}
24:function upgradeCost(level:number){return level<3?1:level<6?2:level<9?3:5}
27:function renderHud(){if(game.screen!=='race')return;const a=game.player;const level=LEVELS[game.levelIndex];const dist=Math.floor(game.distance/10);const goal=Math.round(level.length/10);const spinGoal=Math.max(2,2+Math.floor(game.levelIndex/8));const hGoal=100+game.levelIndex*2;const checks=[a.won||game.distance>=level.length,a.maxSpin>=spinGoal,a.maxHeight>=hGoal,game.distance>=level.length*.8];show(`<div class="race-hud"><div class="hud-top"><div><div class="hud-distance">${dist}<span> m</span></div><div class="hud-level">${esc(level.name)} · ${dist}/${goal} m</div></div><div class="hud-position">${game.actors.filter(o=>o.won||o.x>a.x).length+1}${ordinal(game.actors.filter(o=>o.won||o.x>a.x).length+1)}</div></div><div class="hud-objectives">${checks.map((v,i)=>`<span class="objective ${v?'done':''}">${v?'✓':'○'} ${['1st','Spin','Air','Go'][i]}</span>`).join('')}</div><div style="font-size:clamp(11px,3vw,14px);font-weight:700;color:${a.powerReset>0?'#ff8b67':a.limbs<4?'#ffe16a':'#fff4dc'};text-shadow:0 2px #493046;margin-top:3px">${a.powerReset>0?'⚠ POWER RESET':`LIMBS ${a.limbs}/4 · BOUNCE ×${1+a.bouncePower}`}</div>${game.paused?`<div class="screen"><div class="card"><h2>PAUSED</h2><p>Robot safety inspection in progress.</p><div class="button-row">${btn('RESUME','resume','gold')}${btn('QUIT RACE','quit','secondary')}</div></div></div>`:''}<div class="chip-tracker">${checks.map(v=>`<span class="chip-dot ${v?'done':''}"></span>`).join('')}</div><button id="hold-control" class="hold-control ${game.held?'active':''}"><span class="hold-dot"></span> HOLD TO BRAKE &nbsp;↓</button></div>`);const b=document.querySelector<HTMLButtonElement>('#hold-control');if(b){const down=(e:Event)=>{e.preventDefault();game.held=true;b.classList.add('active')};const up=(e:Event)=>{e.preventDefault();game.held=false;b.classList.remove('active')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointerleave',up);b.addEventListener('pointercancel',up)}}
29:function renderResult(){const r=game.result!;const got=r.awards.filter(Boolean).length;show(`<div class="screen"><div class="card"><div class="topline">${r.place===1?'CHAMPION!':'RACE COMPLETE'}</div><h2>${r.place===1?'Victory!':r.place===2?'So close!':'Good effort!'}</h2><p>${r.place===1?'The robot union has filed a complaint about that boot.':`${esc(game.player.name)} is mostly in one piece. Mostly.`}</p><div class="result-badges">${r.awards.map((ok,i)=>`<div class="result-badge"><strong>${ok?'🟡 +1':'○ 0'}</strong>${['Finish 1st','Spin goal','Jump height','Race distance'][i]}</div>`).join('')}</div><p>Spins: <b>${r.spins}</b> &nbsp; Max air: <b>${r.height}m</b></p><p>Chips earned: <span class="chip-count">${got}</span> &nbsp; Total: <span class="chip-count">${game.chips}</span></p><div class="button-row">${game.levelIndex+1<game.unlocked&&game.levelIndex+1<LEVELS.length?btn('NEXT LEVEL →','next','gold'):btn('RACE AGAIN','again','gold')}${btn('GARAGE & UPGRADES','upgrades','secondary')}${btn('MAIN MENU','menu','secondary')}</div></div></div>`);controls.classList.add('hidden');touchHint.classList.add('hidden');save()}
31:ui.addEventListener('click',e=>{const target=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!target)return;const action=target.dataset.action!;switch(action){case'menu':menu();break;case'howto':howto();break;case'start-tournament':levels('tournament');break;case'quick':levels('quick');break;case'upgrades':upgrades();break;case'settings':settings();break;case'level':selectedLevel=Number(target.dataset.level);levels(activeLevelMode);break;case'start-selected':startRace(selectedLevel,activeLevelMode==='quick'&&quickSolo,sessionPlayers);break;case'toggle-solo':quickSolo=!quickSolo;levels('quick');break;case'buy':{const k=target.dataset.stat as keyof Stats;const cost=upgradeCost(game.stats[k]);if(game.chips>=cost&&game.stats[k]<10){game.chips-=cost;game.stats[k]++;game.stats={...game.stats};save();upgrades()}break}case'bot-minus':game.settingsBot=Math.max(0,game.settingsBot-1);save();settings();break;case'bot-plus':game.settingsBot=Math.min(3,game.settingsBot+1);save();settings();break;case'sound':game.sound=!game.sound;save();settings();break;case'resume':game.paused=false;renderHud();break;case'quit':menu();break;case'again':startRace(game.levelIndex,game.solo);break;case'next':startRace(Math.min(game.levelIndex+1,game.unlocked-1));break}}

